const ALLOWED={'application/pdf':bytes=>String.fromCharCode(...bytes.slice(0,5))==='%PDF-','image/png':bytes=>[137,80,78,71,13,10,26,10].every((n,i)=>bytes[i]===n),'image/jpeg':bytes=>bytes[0]===255&&bytes[1]===216&&bytes[2]===255,'image/webp':bytes=>String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP'};
export async function validateAttachment(file){if(!file||file.size<1||file.size>10*1024*1024||!ALLOWED[file.type])throw Error('Escolha PDF, PNG, JPG ou WebP de até 10 MB.');const bytes=new Uint8Array(await file.slice(0,12).arrayBuffer());if(!ALLOWED[file.type](bytes))throw Error('O conteúdo do arquivo não corresponde ao formato informado.');return true}
export function install(ctx){
 async function storageRequest(path,{method='GET',body,mime}={}){if(!ctx.session)throw Error('Entre novamente para acessar os anexos.');if(ctx.session.expires_at<Date.now()/1000+60)await ctx.refresh();const response=await fetch(ctx.config.url+'/storage/v1/'+path,{method,body,headers:{apikey:ctx.config.key,Authorization:'Bearer '+ctx.session.access_token,...(mime?{'Content-Type':mime,'x-upsert':'false'}:{})},signal:AbortSignal.timeout(60000)});if(!response.ok){const error=await response.json().catch(()=>null);throw Error(error?.message||error?.error||'Não foi possível acessar o arquivo. Tente novamente.')}return response}
 async function attachmentsDialog(type,parent,title='Anexos privados'){
  if(!ctx.can('attachments','view'))return ctx.toast('Seu acesso não permite consultar anexos.');
  const d=ctx.modal(title,`<p class="muted">Os documentos deste registro ficam na base privada da Avelon. Formatos: PDF, PNG, JPG e WebP · até 10 MB por arquivo.</p>${ctx.can('attachments','create')?'<form id="attachment-form"><label class="field">Anexar nota fiscal, recibo ou comprovante<input type="file" name="file" accept="application/pdf,image/png,image/jpeg,image/webp" required></label><button class="primary" type="submit">Enviar anexo</button></form>':''}<p role="status" id="attachment-status"></p><label class="inline-check"><input type="checkbox" id="show-archived-attachments"> Mostrar arquivados</label><div id="attachment-list">Carregando…</div><div class="form-actions"><button class="secondary" data-close>Fechar</button></div>`,{wide:true});
  const status=d.querySelector('#attachment-status'),list=d.querySelector('#attachment-list');let pending=null;
  async function draw(){try{const records=await ctx.api('/rest/v1/document_attachments?parent_type=eq.'+type+'&parent_id=eq.'+parent+'&state=eq.ready&deleted_at=is.null&order=created_at.desc');const shown=records.filter(x=>d.querySelector('#show-archived-attachments').checked||!x.archived);list.innerHTML=shown.length?shown.map(x=>`<div class="history-row"><div><strong>${ctx.esc(x.original_name)}</strong><p class="muted">${ctx.date(x.created_at)} · ${Math.ceil(x.byte_size/1024)} KB${x.archived?' · Arquivado':''}</p></div><button class="secondary small" data-download-attachment="${x.id}">Baixar</button>${ctx.can('attachments','edit')?`<button class="secondary small" data-archive-attachment="${x.id}">${x.archived?'Restaurar':'Arquivar'}</button>`:''}</div>`).join(''):'<p class="muted">Nenhum anexo neste registro.</p>';list.querySelectorAll('[data-download-attachment]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const row=records.find(x=>x.id===button.dataset.downloadAttachment),response=await storageRequest('object/authenticated/avelon-private-documents/'+row.storage_path),url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=row.original_name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='Download iniciado.'}catch(error){status.textContent=error.message}finally{button.disabled=false}});list.querySelectorAll('[data-archive-attachment]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const row=records.find(x=>x.id===button.dataset.archiveAttachment);await ctx.rpc('archive_document_attachment',{p_attachment:row.id,p_archived:!row.archived});await draw();status.textContent=row.archived?'Anexo restaurado.':'Anexo arquivado. O histórico foi preservado.'}catch(error){status.textContent=error.message;button.disabled=false}})}catch(error){list.textContent=error.message}}
  d.querySelector('#show-archived-attachments').onchange=draw;
  d.querySelector('#attachment-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const file=e.target.elements.file.files[0];await validateAttachment(file);status.textContent='Enviando anexo…';if(!pending){pending=await ctx.rpc('reserve_document_attachment',{p_type:type,p_parent:parent,p_name:file.name.slice(0,200),p_mime:file.type,p_bytes:file.size});pending.file=file;pending.uploaded=false}if(pending.file!==file)throw Error('Conclua o envio anterior antes de escolher outro arquivo.');if(!pending.uploaded){await storageRequest('object/avelon-private-documents/'+pending.storage_path,{method:'POST',body:file,mime:file.type});pending.uploaded=true}await ctx.rpc('finish_document_attachment',{p_attachment:pending.id});pending=null;e.target.reset();status.textContent='Anexo salvo com acesso privado.';await draw()}catch(error){status.textContent=error.message+(pending?.uploaded?' O arquivo foi enviado; clique em Enviar anexo para concluir o registro.':'')}finally{button.disabled=false}});
  await draw();
 }
 async function downloadStoredFile(row){const response=await storageRequest('object/authenticated/avelon-private-documents/'+row.storage_path),url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=row.original_name||row.name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
 async function removeStoredFile(path){if(!ctx.profile?.active||!ctx.profile?.is_owner)throw Error('Exclusão exclusiva do Mestre Criador.');await storageRequest('object/avelon-private-documents',{method:'DELETE',body:JSON.stringify({prefixes:[path]}),mime:'application/json'})}
 Object.assign(ctx,{attachmentsDialog,downloadStoredFile,removeStoredFile});
}
